    void UpdateSendControls(){var device=sendTarget.SelectedItem as SendPhone;sendHeading.Text=device==null?"Ready to share":("Send to "+device.Label.Split(" · ")[0]);sendHeading.MaximumSize=new(Math.Max(200,(sendHeading.Parent?.ClientSize.Width??500)-56),0);sendHint.Text=device==null?"Add a device, then select it on the left.":"Files, text and links go to the selected device.";if(fileButton!=null){fileButton.Enabled=device!=null&&outbox!=null&&!stagingFiles;textButton.Enabled=clipboardButton.Enabled=fileButton.Enabled;}recent.Text=outbox?.History().FirstOrDefault() is {} item?item.Name+" · "+FriendlyState(item.State):"No transfers yet. Your history appears in Activity.";}
