    async void SendText(){if(outbox==null||sendTarget.SelectedItem is not SendPhone target)return;using var d=new Form{Text="Send to "+target.Label.Split(" · ")[0],Size=new(540,350),StartPosition=FormStartPosition.CenterParent};var entry=new TextBox{Multiline=true,Dock=DockStyle.Fill,MaxLength=8192,Margin=new(16)};var hint=new Label{Text="Text is copied on a computer. Web links can be opened on the receiver.",Dock=DockStyle.Top,Height=55,Padding=new(12)};var go=new Button{Text="Send text or link",Dock=DockStyle.Bottom,Height=48,DialogResult=DialogResult.OK};d.Controls.Add(entry);d.Controls.Add(hint);d.Controls.Add(go);if(d.ShowDialog(this)!=DialogResult.OK)return;await StageText(target.Id,entry.Text);}
